add('lesson:'+slug,'Container separates organizational data responsibilities, contextual GDPR notice and scoped preservation.',[
 'Profile replaces authored header/summary. Broad5.4/4.8 and Applied are metadata, not precise child scope, calibrated difficulty or legal approval.',
 'The source explicitly distinguishes custodian and steward. Its richer explanation does not repair the separately authored combined-role or processor card. No parent/child approval transfers.'
]);
add('keywords:'+slug,'Four introductory definitions distinguish subject, controller, processor and preservation instruction.',[
 'Interpret privacy labels in the GDPR teaching context, using actual activities and essential purposes/means rather than job title or contract label alone. Other jurisdictions may differ.',
 'All four definitions are inspected; legal hold appears as an alternative but never a correct key in the three delivered questions. Preservation trigger/scope/release depends on applicable law and facts; no universal retention duration.'
]);
add('check:'+slug,'Reveal-only instructed payroll example identifies the likely processor/controller relationship.',[
 'The limited on-behalf-of premise supports the likely roles. Contract wording is evidence, not conclusive designation over actual functions; processor discretion over non-essential implementation can remain.',
 'This ungraded model response accepts no learner answer and supplies no wrong-response feedback, score or independent family. It determines no real payroll provider legal status.'
]);
add('section:'+slug+':0','Distinguish owner accountability, custodian implementation, stewardship and activity-specific privacy roles.',[
 'Organizational titles and combinations vary. Responsibilities can be performed by one person without making all roles interchangeable; owners set business requirements while custodians implement safeguards and stewards commonly coordinate quality/governance.',
 'Controller/processor are contextual GDPR functions, not synonyms for owner/custodian, fixed titles, or a contract-only allocation. A controller decides purposes/essential means; implementation discretion can remain with processors. This precise source does not approve the ambiguous standalone cards.'
]);
add('section:'+slug+':1','Optional enrichment retains controller authority-notice wording and separates individual communication.',[
 'EDPB guidance quotes Article33: controller notice without undue delay, feasible72-hour limit from awareness, unlikely-risk exception, late reasons, and processor prompt notice to controller. Article34 individual communication uses a different high-risk threshold and exceptions.',
 'Observed Beyond index1 stays optional; inherited source tags do not make all GDPR detail mandatory exam scope. No universal72-hour rule for every incident/person, real deadline calculation, jurisdiction/application decision or complete current-law verification.'
]);
add('section:'+slug+':2','Scope preservation and electronic discovery while suspending routine destruction for held information.',[
 'Preservation when litigation is reasonably anticipated is contextual instruction, not a universal cross-jurisdiction trigger. Relevant scope, authority, lawful access and release require actual facts/procedure.',
 'eDiscovery is a collection/review/production process description. Access logs/hashes/custody support handling evidence, not automatic authenticity, completeness, admissibility or permanent retention. No real legal hold, record collection or deletion occurs.'
]);
add('traps:'+slug,'Three cautions retain business accountability, conditional notice and in-scope deletion suspension.',[
 'Owner accountability does not eliminate custodian duties or statutory entity obligations. The GDPR risk/timing caveat and scoped legal hold are read with their full sections.',
 'No every-jurisdiction duty, automatic controller-to-owner identity, guaranteed compliance or retain-everything-forever rule.'
]);
for(let i=0;i<3;i++)add(`practice:${slug}:practice-keyword-${i}`,'Recognize one of the same guide definitions with four offered choices and feedback.',[
 'The correct keys are subject/controller/processor; explanations and wrong-choice feedback repeat the four guide entries. One guide is not three independent scenario assessments or a validated misconception/recovery programme.',
 'Vocabulary reuse, display permutations, retries and best local percentage provide no trusted score, assessed canonical role, family or mastery. Legal-hold alternative does not independently assess preservation.'
]);
add(cardId('Governance'),'Introductory governance connects leadership structures and rules to business, law and risk limits.',[
 'A descriptive organizational framework, not proof rules align in practice, legal compliance, one mandatory governance model or automatic security effectiveness. No specific business policy is assessed.'
]);
add(cardId('Security Steering Committee'),'A leadership review group considers security strategy, risk, policy and priorities.',[
 'A conventional organizational role; names, membership and powers vary. Review is not sole executive/board accountability, statutory controllership or actual policy authorization.'
]);
add(cardId('Data Ownership'),'Assign business responsibility for classification, protection, use and handling.',[
 'Organizational accountability assignment, not property rights or literal possession. Delegating technical tasks does not remove business accountability; ownership is not automatic GDPR controllership.'
]);
add(cardId('Data Owner'),'A conventional business owner sets classification, protection requirements and approved use.',[
 'Senior business role is a common organizational pattern, not universal required rank or a fixed job title. Distinguish accountable decisions from technical implementation; actual delegated powers and statutory obligations still matter.'
]);
add(cardId('Data Controller'),'Introductory privacy term describes determining why and how personal data is processed.',[
 'Bound to the GDPR lesson context: actual purposes/essential means determine roles; technical implementation can be delegated. Not every data owner, senior employee or service provider is the legal controller, and other laws may define roles differently.'
]);
add(cardId('Data Processor'),'Hold the on-behalf-of card because its unqualified third-party label is ambiguous.',[
 'HOLD: the authored card calls a processor a Third party. Colloquial external-provider usage is understandable, but GDPR Article4(10), as explained by EDPB paragraphs86-89, excludes the processor from third party in that same processing relationship.',
 'Require owner-reviewed wording for a separate entity processing on the controller behalf, with context and functional determination. No source rewrite or reuse of the richer lesson to clear this card; zero content/link/family/mastery credit.'
],true);
add(cardId('Data Custodian / Steward'),'Hold the compound card because it collapses stewardship into technical custody.',[
 'HOLD: one combined label supplies only technical storage/backup/access/retention work; it does not distinguish the lesson steward quality/governance coordination from custodian implementation.',
 'Roles can overlap or be combined by policy, but the standalone source provides no context supporting interchangeability. Require separate precise meanings or an explicit organization-specific combined role, owner-reviewed; zero content/link/family/mastery credit.'
],true);
